#include <iostream>

template <typename T>
struct Formatter {
    static void print(T v) { std::cout << "Generic: " << v << "\n"; }
};

// Full Specialization for bool
template <>
struct Formatter<bool> {
    static void print(bool v) { std::cout << (v ? "true" : "false") << "\n"; }
};

